std::vector<VideoResult> sortResults(const std::vector<VideoResult>& results, const std::string& sortBy, const std::string& sortOrder) {
  std::vector<VideoResult> sortedResults = results;
  if (sortBy == "name") {
    if (sortOrder == "asc") {
      std::sort(sortedResults.begin(), sortedResults.end(), [](const VideoResult& a, const VideoResult& b) { return a.name < b.name; });
    } else if (sortOrder == "desc") {
      std::sort(sortedResults.begin(), sortedResults.end(), [](const VideoResult& a, const VideoResult& b) { return a.name > b.name; });
    }
  } else if (sortBy == "size") {
    if (sortOrder == "asc") {
      std::sort(sortedResults.begin(), sortedResults.end(), [](const VideoResult& a, const VideoResult& b) { return a.size < b.size; });
    } else if (sortOrder == "desc") {
      std::sort(sortedResults.begin(), sortedResults.end(), [](const VideoResult& a, const VideoResult& b) { return a.size > b.size; });
    }
  } else if (sortBy == "site") {
    if (sortOrder == "asc") {
      std::sort(sortedResults.begin(), sortedResults.end(), [](const VideoResult& a, const VideoResult& b) { return a.site < b.site; });
    } else if (sortOrder == "desc") {
      std::sort(sortedResults.begin(), sortedResults.end(), [](const VideoResult& a, const VideoResult& b) { return a.site > b.site; });
    }
  }
  return sortedResults;
}

